from __future__ import absolute_import
import re
import time
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.common.exceptions import ObjectNotFoundException
from taf.selenium.sbts_fsm3.pages.panels.navigation import NavigationPanel
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.panels.details import DetailPanel
from taf.selenium.sbts_fsm3.pages.modals import (LoadScfFileModal, ActivatePlanModal,
                                            SaveBtsConfigurationModal, AddObjectModal,
                                            RemoveObjectModal, UndoChangesModal,
                                            SaveReportModal, CreateNewConfigurationModal,
                                            UndoObjectChangesModal)


class ConfigurationCommonAction(NavigationPanel, ViewPanel, DetailPanel):
    _LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT = "load-action-button input"
    _CREATE_CONFIGURATION_BUTTON_XPATH = '//create-configuration-button//button'
    _LOAD_COMMISSIONING_FILE_BUTTON_XPATH = '//load-action-button//input'
    _UNDO_CHANGES_BUTTON_XPATH = '//undo-changes-action-button//button'
    _VALIDATE_PLAN_BUTTON_XPATH = '//revalidate-action-button//button'
    _ACTIVATE_PLAN_BUTTON_XPATH = '//deploy-action-button//button'
    _SAVE_REPORT_BUTTON_XPATH = '//commissioning-report//button'
    _SAVE_BTS_CONFIGURATION_ICON_XPATH = '//save-bts-configuration-button//button'
    _OBJECT_NAME_FILTER_XPATH = '//ui-text-input[@a-type="filter" and @a-placeholder="Object name"]//input'
    _OBJECT_NAME_XPATH = '(//span[@title="{}" or @aria-label="{}"])'
    _ADD_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="plus"]/button'
    _REMOVE_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="trash"]/button'
    _UNDO_OBJECT_CHANGES_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="undo"]/button'
    _VALID_OBJECT_XPATH = ('//*[contains(text(), "{}")]/ancestor::*[contains(@class, '
                           'tree-list-grouping-renderer ng-scope)]//span[@aria-label="{}"]')
    _VALID_OBJECT_BASE_XPATH = '//ui-expandable-panel-header[contains(text(), "{}")]/ancestor::ui-expandable-panel/'
    _TARGET_OBJECT_XPATH = '/following-sibling::li[div//span[@aria-label="{}"]][1]'
    _OBJECT_NAME_MAP_XPATH = ('//*[contains(text(), "{}")]/ancestor::*[contains(@class, '
                              '"tree-list-grouping-renderer ng-scope")]//span[contains(@aria-label, "{}")]')
    _LOADING_SCREEN = '//*[@id="loading-screen"]'
    _INACTIVE_CONFIGURATION_XPATH = ('//*[contains(text(), "Inactive BTS configurations")]'
                                     '/ancestor::div[div[@class="ui-expandable-panel-header"]]'
                                     '//following-sibling::div[contains(@class, "ui-expandable-panel-body")]'
                                     '//li[@role="button"]')
    _SCROLL_TOP = 'return document.querySelector(\'global-search-tab-content div[virtual-scroll="true"]\').scrollTop'
    _SCROLL = ('var scroll_bar = document.querySelector(\'global-search-tab-content div[virtual-scroll="true"]\'); '
               'if (scroll_bar){{scroll_bar.scrollTop={};}}')
    _CHECK_IF_ON_BOTTOM = (
        'var scroll_bar = document.querySelector(\'global-search-tab-content div[virtual-scroll="true"]\'); if ('
        'scroll_bar.scrollHeight - scroll_bar.scrollTop - scroll_bar.clientHeight < 2) {{return 1}} else {{return 0}} ')
    _STEP = 120
    _instance = None
    _CURRENT = 'Current'
    _SUB_STR = r'\/following-sibling::li\[div\/\/span\[\@aria-label="{}"\]\]\[1\]'
    _DISTANCE_FROM_STOP = 0

    def __init__(self, driver, download_checker=None, screenshot_dir=None):
        super(ConfigurationCommonAction, self).__init__(driver, download_checker, screenshot_dir)

    def _go_to_target_object(self, bts_configuration, object_name_list, scroll_time=45):  # noqa: C901
        previous = self._VALID_OBJECT_BASE_XPATH.format(bts_configuration)
        single = False
        located = False
        for index, object_name in enumerate(object_name_list):
            head_o = re.findall('aria-label="(.*?)"', previous)
            if (object_name_list[index - 1] not in head_o and index != 0) or (single is True and located is False):
                raise ObjectNotFoundException("can not locate {} in route {} on "
                                              "webem".format(object_name_list[index - 1], "/".join(object_name_list)))

            current = previous + self._TARGET_OBJECT_XPATH.format(object_name)
            for loop in range(0, scroll_time):

                try:
                    elem = self.wait_for_enable((By.XPATH, current), 1)
                    previous = current
                    break
                except TimeoutException:
                    if not self.driver.execute_script(self._CHECK_IF_ON_BOTTOM):
                        scroll_top = float(self.driver.execute_script(self._SCROLL_TOP))
                        self.driver.execute_script(self._SCROLL.format(scroll_top + self._STEP))
                        time.sleep(0.5)
                try:
                    elem = self.wait_for_enable((By.XPATH, current), 0.8)
                    previous = current
                    located = True
                    break
                except TimeoutException:
                    located = False
                    if len(re.findall('aria-label="(.*?)"', current)) == 1:
                        single = True
                        continue

                try:
                    elem = self.wait_for_enable((By.XPATH, previous), 0.8)
                    continue
                except TimeoutException:
                    head_o = re.findall('aria-label="(.*?)"', previous)[0]
                    current = re.sub(self._SUB_STR.format(head_o), '', current)
                    previous = current

        return elem

    def _input_and_choose_object(self, object_name, timeout=60, bts_configuration='Current'):
        """
        Choose object after inputting object name
        :param object_name: str, where object will be added in
        :param timeout: int, timeout
        """
        self.driver.execute_script(self._SCROLL.format(self._DISTANCE_FROM_STOP))
        bts_configuration = bts_configuration.lower().capitalize()
        object_name_list = object_name.split('/')
        last_level_object_name = object_name_list[-1]
        self._input_object(last_level_object_name, bts_configuration, timeout)
        self._choose_object(object_name_list, bts_configuration)
        return last_level_object_name

    def _input_object(self, object_name, bts_configuration, timeout):
        self.driver.execute_script(self._SCROLL.format(self._DISTANCE_FROM_STOP))
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._OBJECT_NAME_FILTER_XPATH),
                                                     object_name,
                                                     timeout)
        if self._CURRENT != bts_configuration:
            current_tab_xpath = self._VALID_OBJECT_BASE_XPATH.format('Current') + '/*[@role="tab"]//i'
            if 'true' == self.get_attribute_by_xpath(current_tab_xpath, 'aria-expanded'):
                self.click_enabled_element((By.XPATH, current_tab_xpath), 3)

    def _choose_object(self, object_name_list, bts_configuration):
        elem = self._go_to_target_object(bts_configuration, object_name_list)
        self.driver.execute_script("arguments[0].scrollIntoView();", elem)
        elem.click()

    def add_object(self, object_name, object_class_name, plan_to_copy_from, copy_from, include_subobject, id_value,
                   is_load_default_values, timeout):
        """
        Adding object under navigation panel
        :param object_name: str, where object will be added in
        :param object_class_name: str, name of object class
        :param plan_to_copy_from: str, where plan to copy object from
        :param copy_from: str, where copy object from
        :param include_subobject: boolean
        :param id_value: str, default is None
        :param is_load_default_values: boolean
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name)
        self.click_enabled_element((By.XPATH, self._ADD_OBJECT_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        add_object_modal = AddObjectModal(self.driver)
        add_object_modal.wait_until_add_object_modal_appear(timeout)
        add_object_modal.add_object(object_class_name,
                                    plan_to_copy_from,
                                    copy_from,
                                    include_subobject,
                                    id_value,
                                    is_load_default_values,
                                    timeout)
        add_object_modal.submit(timeout)

    def remove_object(self, object_name, timeout=60, raise_non_exist=False):
        """
        Remove object under navigation panel
        :param object_name: str, object will be removed
        :param timeout: int, timeout
        """
        try:
            object_name = self._input_and_choose_object(object_name, timeout)
        except ObjectNotFoundException as msg:
            if not raise_non_exist:
                return
            else:
                raise ObjectNotFoundException(msg)

        self.click_enabled_element((By.XPATH, self._REMOVE_OBJECT_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        remove_object_modal = RemoveObjectModal(self.driver)
        remove_object_modal.wait_until_remove_object_modal_appear(timeout)
        remove_object_modal.submit(timeout)

    def undo_object_changes(self, object_name, timeout=60):
        """
        Remove object under navigation panel
        :param object_name: str, object will be removed
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name, timeout)
        self.click_enabled_element((By.XPATH, self._UNDO_OBJECT_CHANGES_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        undo_object_changes_modal = UndoObjectChangesModal(self.driver)
        undo_object_changes_modal.wait_until_undo_object_changes_modal_appear(timeout)
        undo_object_changes_modal.submit(timeout)

    def create_plan(self, is_copy, copy_configuration_from, configuration_name, timeout):
        self.click_enabled_element((By.XPATH, self._CREATE_CONFIGURATION_BUTTON_XPATH), timeout)
        configuration_modal = CreateNewConfigurationModal(self.driver)
        configuration_modal.wait_for_creat_new_configuration_modal_appear(timeout)
        configuration_modal.create_new_configuration(is_copy, copy_configuration_from, configuration_name, timeout)

    def load_commissioning_file_and_check_load_status(self, file_path, timeout=60):
        """
        Load commissioning file and check load status
        :param file_path: str, scf file path
        :param timeout: int, timeout
        :return: boolean, True or False
        """
        self.load_file_from_hidden_button(self._LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT,
                                          self._LOAD_COMMISSIONING_FILE_BUTTON_XPATH, file_path, timeout)
        load_scf_file_modal = LoadScfFileModal(self.driver)
        load_scf_file_modal.wait_until_load_file_modal_appear(timeout)
        load_status = load_scf_file_modal.check_status_after_loading_scf_file(timeout)
        load_scf_file_modal.confirm()
        return load_status

    def undo_changes(self, timeout=60):
        """
        Undo changes
        :param timeout: int, timeout
        """
        self.click_enabled_element((By.XPATH, self._UNDO_CHANGES_BUTTON_XPATH), timeout)

        undo_changes_modal = UndoChangesModal(self.driver)
        undo_changes_modal.wait_until_undo_changes_modal_appear(timeout)
        undo_changes_modal.execute_undo_changes(timeout)

    def validate_plan(self, timeout=60):
        """
        Validate definition errors plan
        :return: str, validation result
        """
        self.click_enabled_element((By.XPATH, self._VALIDATE_PLAN_BUTTON_XPATH), timeout)
        try:
            self.wait_for_text_present_in_attribute(self._LOADING_SCREEN, 'aria-hidden', 'false', timeout)
        except TimeoutException:
            pass
        self.wait_for_text_present_in_attribute(self._LOADING_SCREEN, 'aria-hidden', 'true', timeout)

    def activate_plan(self, download_plan_without_activation=False,
                      activate_plan_despite_errors=False, execute=True, activate_inactive_plan=False, timeout=60):
        """
        Activate plan after loading scf file
        :param download_plan_without_activation: boolean, if False, download plan without activation will not be
        selected, default False
        :param activate_plan_despite_errors: boolean, if True, activate or download plan despite of validation errors
        will be selected, default False
        :param execute: boolean, if True, click execute button, otherwise close the activate plan modal
        :param timeout: int, timeout
        :return: boolean, if True, activate successfully, otherwise, activate failed
        """
        activate_status = False
        if activate_inactive_plan:
            self.wait_for_visibility_by_xpath(self._INACTIVE_CONFIGURATION_XPATH)
            self.click_enabled_element((By.XPATH, self._INACTIVE_CONFIGURATION_XPATH), timeout)

        try:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_PLAN_BUTTON_XPATH), timeout=20)
        except TimeoutException:
            return activate_status

        activate_plan_modal = ActivatePlanModal(self.driver)
        activate_plan_modal.wait_until_actiavte_plan_modal_appear(timeout)
        if not activate_inactive_plan:
            activate_plan_modal.select_download_plan_without_activation(download_plan_without_activation)
        activate_plan_modal.select_activate_or_download_plan_despite_errors(activate_plan_despite_errors, timeout=10)

        if execute:
            activate_status = activate_plan_modal.execute(timeout)
        activate_plan_modal.close(timeout)
        return activate_status

    def save_report(self, timeout=60):
        """
        Save report
        :param timeout: int, timeout
        :return: str, report path
        """
        self.click_enabled_element((By.XPATH, self._SAVE_REPORT_BUTTON_XPATH))

        save_report_modal = SaveReportModal(self.driver, self._download_checker)
        save_report_modal.wait_until_save_report_modal_appear(timeout)
        report_file_path = save_report_modal.save_report(timeout)
        save_report_modal.close(timeout)
        return report_file_path

    def save_bts_configuration(self, save_configuration_type_str, save_planned_parameter_changes):
        """
        Keyword for save bts configuration
        :param save_configuration_type_str: str, type of save type
                0: Save as SCF - BTS configuration only
                1: Save as full BTS runtime configuration
                2: Save BTS runtime information only
        :param save_planned_parameter_changes: bool, save the planned parameter changes or not
        :return str, path to download configuration file
        """
        self.click_enabled_element_after_visible((By.XPATH, self._SAVE_BTS_CONFIGURATION_ICON_XPATH))
        save_configuration_modal = SaveBtsConfigurationModal(self.driver, self._download_checker)
        save_configuration_modal.wait_until_save_bts_configuration_modal_appear()
        return save_configuration_modal.save(save_configuration_type_str, save_planned_parameter_changes)
